43	// Client provides an enhanced interface for interacting with Sentry error tracking.
44	// It wraps the official Sentry Go SDK and adds automatic tag enrichment from context
45	// and errors, configurable error filtering, and enhanced integration with github.com/bborbe/errors.
46	type Client interface {
47		CaptureMessage(
48			message string,
49			hint *sentry.EventHint,
50			scope sentry.EventModifier,
51		) *sentry.EventID
52		CaptureException(
53			exception error,
54			hint *sentry.EventHint,
55			scope sentry.EventModifier,
56		) *sentry.EventID
57		Flush(timeout stdtime.Duration) bool
58		io.Closer
59	}
