61	// NewClient creates a new Sentry client with enhanced functionality including automatic
62	// tag enrichment and error filtering. It accepts standard Sentry ClientOptions and optional
63	// ExcludeError functions to filter out specific errors from being sent to Sentry.
64	//
65	// WARNING: Do not pass sensitive information (passwords, API keys, PII, tokens) in hint.Data,
66	// context data, or error data as these will be sent to Sentry as tags and may be stored or
67	// logged externally.
68	func NewClient(
69		ctx context.Context,
70		clientOptions sentry.ClientOptions,
71		excludeErrors ...ExcludeError,
72	) (Client, error) {
73		newClient, err := sentry.NewClient(clientOptions)
74		if err != nil {
75			return nil, errors.Wrap(ctx, err, "create sentry client failed")
76		}
77		newClient.AddEventProcessor(enrichEventTags)
78		return &client{
79			client:        newClient,
80			excludeErrors: excludeErrors,
81		}, nil
82	}
83	
84	func enrichEventTags(event *sentry.Event, hint *sentry.EventHint) *sentry.Event {
85		if event.Tags == nil {
86			event.Tags = make(map[string]string)
87		}
88		addContextTags(event, hint)
89		addErrorTags(event, hint)
90		addHintDataTags(event, hint)
91		return event
92	}
93	
94	func addContextTags(event *sentry.Event, hint *sentry.EventHint) {
95		if hint.Context == nil {
96			return
97		}
98		for k, v := range errors.DataFromContext(hint.Context) {
99			event.Tags[k] = fmt.Sprintf("%v", v)
100		}
101	}
102	
103	func addErrorTags(event *sentry.Event, hint *sentry.EventHint) {
104		if hint.OriginalException == nil {
105			return
106		}
107		for k, v := range errors.DataFromError(hint.OriginalException) {
108			event.Tags[k] = fmt.Sprintf("%v", v)
109		}
110	}
111	
112	func addHintDataTags(event *sentry.Event, hint *sentry.EventHint) {
113		switch data := hint.Data.(type) {
114		case map[string]any:
115			for k, v := range data {
116				if v == nil {
117					continue
118				}
119				event.Tags[k] = fmt.Sprintf("%v", v)
120			}
121		case map[string]string:
122			maps.Copy(event.Tags, data)
123		}
124	}
