135	func (c *client) CaptureMessage(
136		message string,
137		hint *sentry.EventHint,
138		scope sentry.EventModifier,
139	) *sentry.EventID {
140		eventID := c.client.CaptureMessage(message, hint, scope)
141		if eventID != nil {
142			glog.V(2).Infof("capture sentry message with id %s", *eventID)
143		} else {
144			glog.V(2).Infof("capture sentry message failed: eventID is nil")
145		}
146		return eventID
147	}
148	
149	func (c *client) CaptureException(
150		err error,
151		hint *sentry.EventHint,
152		scope sentry.EventModifier,
153	) *sentry.EventID {
154		if c.excludeErrors.IsExcluded(err) {
155			glog.V(4).Infof("capture error %v is excluded => skip", err)
156			return nil
157		}
158		if scope == nil {
159			scope = sentry.NewScope()
160		}
161		if hint == nil {
162			hint = &sentry.EventHint{}
163		}
164		if hint.OriginalException == nil {
165			hint.OriginalException = err
166		}
167		eventID := c.client.CaptureException(err, hint, scope)
168		if eventID != nil {
169			glog.V(3).Infof("capture sentry exception with id %s", *eventID)
170		} else {
171			glog.V(2).Infof("capture sentry exception failed: eventID is nil")
172		}
173		return eventID
174	}
175	
176	func (c *client) Close() error {
177		c.client.Flush(2 * stdtime.Second)
178		return nil
179	}
