func specIDsFromPaths(paths []string) []string {
	ids := make([]string, 0, len(paths))
	for _, p := range paths {
		base := filepath.Base(p)
		ids = append(ids, strings.TrimSuffix(base, filepath.Ext(base)))
	}
	return ids
