		a.ClaudeConfigDir,
		a.AgentDir,
		a.AnthropicModel,
		ghToken,
		claudeEnv,
		repoManager,
		githubClient,
		claudeProber,
		// Local CLI path: the credential is the operator's own long-lived gh
